// apps/mobile/src/core/rng.ts
function hash32(input) {
  let h = 2166136261;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
function random01(seed, index) {
  let x = hash32(seed) + Math.imul(index + 1, 2654435761) >>> 0;
  x ^= x << 13;
  x ^= x >>> 17;
  x ^= x << 5;
  return (x >>> 0) / 4294967296;
}

// apps/mobile/src/core/character-creation.ts
function characterNameError(value) {
  const name = value.trim();
  if (name.length < 2) return "Use at least 2 characters.";
  if (name.length > 20) return "Use no more than 20 characters.";
  if (!/^\p{L}[\p{L}\p{M} '\-]*$/u.test(name)) return "Use letters, spaces, apostrophes, or hyphens.";
  return "";
}

